{
  "name": "github-tab-deduper",
  "version": "1.0.0",
  "private": true,
  "description": "Chrome extension: reuse existing GitHub PR/issue/discussion tabs instead of opening duplicates.",
  "type": "module",
  "scripts": {
    "test": "node --test",
    "icons": "node scripts/make-icons.mjs",
    "package": "node scripts/package.mjs"
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  parseThreadUrl,
  canonicalKey,
  duplicateTabIds,
  DEFAULT_SETTINGS,
} from '../lib/github.js';

test('parses a pull request URL', () => {
  const parsed = parseThreadUrl('https://github.com/cline/cline/pull/1234');
  assert.deepEqual(parsed, {
    key: 'cline/cline/thread/1234',
    subview: '',
    hash: '',
    href: 'https://github.com/cline/cline/pull/1234',
  });
});

test('issues and pull requests share a key (same number space)', () => {
  const issue = parseThreadUrl('https://github.com/o/r/issues/42');
  const pull = parseThreadUrl('https://github.com/o/r/pull/42');
  assert.equal(issue.key, pull.key);
});

test('discussions get their own key', () => {
  const discussion = parseThreadUrl('https://github.com/o/r/discussions/42');
  const issue = parseThreadUrl('https://github.com/o/r/issues/42');
  assert.notEqual(discussion.key, issue.key);
});

test('owner and repo are case-insensitive', () => {
  const a = parseThreadUrl('https://github.com/Cline/Cline/pull/7');
  const b = parseThreadUrl('https://github.com/cline/cline/pull/7');
  assert.equal(a.key, b.key);
});

test('captures PR subviews, including nested paths', () => {
  assert.equal(parseThreadUrl('https://github.com/o/r/pull/1/files').subview, 'files');
  assert.equal(parseThreadUrl('https://github.com/o/r/pull/1/commits/abc123').subview, 'commits');
  assert.equal(parseThreadUrl('https://github.com/o/r/pull/1/checks').subview, 'checks');
  assert.equal(parseThreadUrl('https://github.com/o/r/pull/1').subview, '');
});

test('ignores unknown subviews and subviews on issues', () => {
  assert.equal(parseThreadUrl('https://github.com/o/r/pull/1/bogus').subview, '');
  assert.equal(parseThreadUrl('https://github.com/o/r/issues/1/files').subview, '');
});

test('keeps the fragment and full href', () => {
  const parsed = parseThreadUrl(
    'https://github.com/o/r/pull/9/files#r123456789',
  );
  assert.equal(parsed.hash, '#r123456789');
  assert.equal(parsed.href, 'https://github.com/o/r/pull/9/files#r123456789');
});

test('query strings do not affect the key', () => {
  const a = parseThreadUrl('https://github.com/o/r/pull/5?notification_referrer_id=xyz');
  const b = parseThreadUrl('https://github.com/o/r/pull/5');
  assert.equal(a.key, b.key);
});

test('accepts www and http variants', () => {
  assert.ok(parseThreadUrl('https://www.github.com/o/r/pull/1'));
  assert.ok(parseThreadUrl('http://github.com/o/r/pull/1'));
});

test('rejects non-thread and non-GitHub URLs', () => {
  assert.equal(parseThreadUrl('https://github.com/o/r'), null);
  assert.equal(parseThreadUrl('https://github.com/o/r/pulls'), null);
  assert.equal(parseThreadUrl('https://github.com/o/r/pull/abc'), null);
  assert.equal(parseThreadUrl('https://github.com/o/r/commit/abc123'), null);
  assert.equal(parseThreadUrl('https://gist.github.com/o/abc'), null);
  assert.equal(parseThreadUrl('https://example.com/o/r/pull/1'), null);
  assert.equal(parseThreadUrl('chrome://newtab/'), null);
  assert.equal(parseThreadUrl('not a url'), null);
});

test('org-level discussions parse consistently', () => {
  const a = parseThreadUrl('https://github.com/orgs/community/discussions/50');
  const b = parseThreadUrl('https://github.com/orgs/community/discussions/50#discussioncomment-1');
  assert.equal(a.key, b.key);
});

test('canonicalKey collapses subviews only when asked', () => {
  const parsed = parseThreadUrl('https://github.com/o/r/pull/3/files');
  assert.equal(canonicalKey(parsed, true), 'o/r/thread/3');
  assert.equal(canonicalKey(parsed, false), 'o/r/thread/3/files');
});

test('duplicateTabIds keeps the most recently accessed tab per thread', () => {
  const tabs = [
    { id: 1, url: 'https://github.com/o/r/pull/1', lastAccessed: 100 },
    { id: 2, url: 'https://github.com/o/r/pull/1/files', lastAccessed: 300 },
    { id: 3, url: 'https://github.com/o/r/pull/1#issuecomment-9', lastAccessed: 200 },
    { id: 4, url: 'https://github.com/o/r/pull/2', lastAccessed: 50 },
  ];
  assert.deepEqual(duplicateTabIds(tabs, true).sort(), [1, 3]);
});

test('duplicateTabIds prefers an active tab over a more recent one', () => {
  const tabs = [
    { id: 1, url: 'https://github.com/o/r/issues/5', active: true, lastAccessed: 100 },
    { id: 2, url: 'https://github.com/o/r/issues/5', lastAccessed: 900 },
  ];
  assert.deepEqual(duplicateTabIds(tabs, true), [2]);
});

test('duplicateTabIds respects the subview setting', () => {
  const tabs = [
    { id: 1, url: 'https://github.com/o/r/pull/1', lastAccessed: 1 },
    { id: 2, url: 'https://github.com/o/r/pull/1/files', lastAccessed: 2 },
  ];
  assert.deepEqual(duplicateTabIds(tabs, true), [1]);
  assert.deepEqual(duplicateTabIds(tabs, false), []);
});

test('duplicateTabIds ignores non-thread tabs and singletons', () => {
  const tabs = [
    { id: 1, url: 'https://github.com/o/r' },
    { id: 2, url: 'https://github.com/o/r' },
    { id: 3, url: 'https://github.com/o/r/pull/1' },
    { id: 4, url: 'https://example.com/o/r/pull/1' },
    { id: 5 },
  ];
  assert.deepEqual(duplicateTabIds(tabs, true), []);
});

test('default settings ship enabled', () => {
  assert.equal(DEFAULT_SETTINGS.enabled, true);
  assert.equal(DEFAULT_SETTINGS.jumpToFragment, true);
  assert.equal(DEFAULT_SETTINGS.collapseSubviews, true);
});

{
  "manifest_version": 3,
  "name": "GitHub Tab De-duper",
  "version": "1.0.0",
  "description": "Opening a GitHub pull request, issue, or discussion you already have open focuses the existing tab instead of creating a duplicate.",
  "background": {
    "service_worker": "background.js",
    "type": "module"
  },
  "permissions": ["storage"],
  "host_permissions": ["https://github.com/*"],
  "action": {
    "default_title": "GitHub Tab De-duper",
    "default_popup": "panel/panel.html",
    "default_icon": {
      "16": "icons/icon16.png",
      "32": "icons/icon32.png",
      "48": "icons/icon48.png",
      "128": "icons/icon128.png"
    }
  },
  "options_ui": {
    "page": "panel/panel.html",
    "open_in_tab": false
  },
  "icons": {
    "16": "icons/icon16.png",
    "32": "icons/icon32.png",
    "48": "icons/icon48.png",
    "128": "icons/icon128.png"
  }
}

import {
  DEFAULT_SETTINGS,
  parseThreadUrl,
  canonicalKey,
} from './lib/github.js';

// Tabs created without a destination URL (about:blank, the new-tab page).
// Their first real navigation is still "opening a link in a new tab", so we
// deduplicate it; anything after that is the user browsing within the tab.
const freshTabs = new Set();

let cachedSettings = null;

async function getSettings() {
  if (!cachedSettings) {
    cachedSettings = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  }
  return cachedSettings;
}

chrome.storage.onChanged.addListener((_changes, area) => {
  if (area === 'sync') cachedSettings = null;
});

function isBlank(url) {
  return (
    !url ||
    url === 'about:blank' ||
    url.startsWith('chrome://newtab') ||
    url.startsWith('chrome://new-tab-page')
  );
}

chrome.tabs.onCreated.addListener((tab) => {
  const url = tab.pendingUrl || tab.url;
  if (isBlank(url)) {
    freshTabs.add(tab.id);
    return;
  }
  void dedupe(tab, url);
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (!changeInfo.url || !freshTabs.has(tabId)) return;
  freshTabs.delete(tabId);
  void dedupe(tab, changeInfo.url);
});

chrome.tabs.onRemoved.addListener((tabId) => {
  freshTabs.delete(tabId);
});

/**
 * If `url` is a GitHub thread that is already open in another tab, focus that
 * tab (navigating it when the link targets a specific comment) and close the
 * newly created duplicate.
 */
async function dedupe(newTab, url) {
  try {
    const settings = await getSettings();
    if (!settings.enabled) return;

    const incoming = parseThreadUrl(url);
    if (!incoming) return;
    const incomingKey = canonicalKey(incoming, settings.collapseSubviews);

    const githubTabs = await chrome.tabs.query({ url: 'https://github.com/*' });
    const existing = githubTabs
      .filter((tab) => {
        if (tab.id === newTab.id || !tab.url) return false;
        const parsed = parseThreadUrl(tab.url);
        return (
          parsed !== null &&
          canonicalKey(parsed, settings.collapseSubviews) === incomingKey
        );
      })
      .sort((a, b) => (b.lastAccessed ?? 0) - (a.lastAccessed ?? 0))[0];
    if (!existing) return;

    // A fragment means the link points at a specific comment or review
    // thread; navigate the existing tab so the browser scrolls to it. A bare
    // thread link just focuses the tab without disturbing the user's place.
    const shouldNavigate =
      settings.jumpToFragment &&
      incoming.hash !== '' &&
      existing.url !== incoming.href;

    await chrome.tabs.update(existing.id, {
      active: true,
      ...(shouldNavigate ? { url: incoming.href } : {}),
    });
    if (existing.windowId !== undefined) {
      await chrome.windows.update(existing.windowId, { focused: true });
    }
    try {
      await chrome.tabs.remove(newTab.id);
    } catch {
      // The duplicate tab is already gone; nothing to clean up.
    }

    const { tabsDeduped = 0 } = await chrome.storage.local.get('tabsDeduped');
    await chrome.storage.local.set({ tabsDeduped: tabsDeduped + 1 });
  } catch (error) {
    console.error('One Tab for GitHub: dedupe failed', error);
  }
}

// URL canonicalization for GitHub "thread" pages: pull requests, issues,
// and discussions — the pages that accumulate duplicate tabs.

export const DEFAULT_SETTINGS = Object.freeze({
  // Master switch for the whole extension.
  enabled: true,
  // When a link targets a specific comment (#issuecomment-…, #discussion_r…),
  // navigate the existing tab there so it scrolls to the comment.
  jumpToFragment: true,
  // Treat a PR's Conversation / Files changed / Commits / Checks views as the
  // same tab. When off, each view deduplicates independently.
  collapseSubviews: true,
});

const THREAD_TYPES = new Set(['pull', 'issues', 'discussions']);
const PR_SUBVIEWS = new Set(['files', 'commits', 'checks']);

/**
 * Parse a URL into a GitHub thread reference, or null if it isn't one.
 *
 * Issues and pull requests share one number space per repo (and GitHub
 * redirects /issues/N to /pull/N when N is a PR), so both canonicalize to the
 * same key. Discussions are numbered independently and keep their own key.
 *
 * @param {string} rawUrl
 * @returns {{key: string, subview: string, hash: string, href: string} | null}
 */
export function parseThreadUrl(rawUrl) {
  let url;
  try {
    url = new URL(rawUrl);
  } catch {
    return null;
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return null;
  if (url.hostname.replace(/^www\./, '') !== 'github.com') return null;

  const segments = url.pathname.split('/').filter(Boolean);
  if (segments.length < 4) return null;
  const [owner, repo, type, number, maybeSubview] = segments;
  if (!THREAD_TYPES.has(type)) return null;
  if (!/^\d+$/.test(number)) return null;

  const kind = type === 'discussions' ? 'discussions' : 'thread';
  const subview =
    type === 'pull' && PR_SUBVIEWS.has(maybeSubview) ? maybeSubview : '';

  return {
    key: `${owner.toLowerCase()}/${repo.toLowerCase()}/${kind}/${number}`,
    subview,
    hash: url.hash,
    href: url.href,
  };
}

/**
 * The identity used to decide whether two tabs are "the same page".
 *
 * @param {{key: string, subview: string}} parsed
 * @param {boolean} collapseSubviews
 * @returns {string}
 */
export function canonicalKey(parsed, collapseSubviews) {
  if (collapseSubviews || !parsed.subview) return parsed.key;
  return `${parsed.key}/${parsed.subview}`;
}

/**
 * Given already-open tabs, pick the duplicates to close: for each group of
 * tabs showing the same thread, every tab except the best one to keep —
 * preferring the active tab, then the most recently accessed.
 *
 * @param {Array<{id?: number, url?: string, active?: boolean, lastAccessed?: number}>} tabs
 * @param {boolean} collapseSubviews
 * @returns {number[]} tab ids to close
 */
export function duplicateTabIds(tabs, collapseSubviews) {
  const groups = new Map();
  for (const tab of tabs) {
    if (tab.id === undefined || !tab.url) continue;
    const parsed = parseThreadUrl(tab.url);
    if (!parsed) continue;
    const key = canonicalKey(parsed, collapseSubviews);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(tab);
  }

  const ids = [];
  for (const group of groups.values()) {
    if (group.length < 2) continue;
    const keep = group.reduce((best, tab) => {
      if (Boolean(tab.active) !== Boolean(best.active)) {
        return tab.active ? tab : best;
      }
      return (tab.lastAccessed ?? 0) > (best.lastAccessed ?? 0) ? tab : best;
    });
    for (const tab of group) {
      if (tab.id !== keep.id) ids.push(tab.id);
    }
  }
  return ids;
}

import { DEFAULT_SETTINGS, duplicateTabIds } from '../lib/github.js';

const statsEl = document.getElementById('stats');
const dedupeButton = document.getElementById('dedupe-now');
const dedupeStatus = document.getElementById('dedupe-status');

async function refreshStats() {
  const { tabsDeduped = 0 } = await chrome.storage.local.get('tabsDeduped');
  if (tabsDeduped === 0) {
    statsEl.textContent = 'Watching for duplicate tabs';
    return;
  }
  const count = document.createElement('span');
  count.className = 'stat-count';
  count.textContent = tabsDeduped.toLocaleString();
  statsEl.replaceChildren(
    'Saved you from ',
    count,
    ` duplicate ${tabsDeduped === 1 ? 'tab' : 'tabs'}`,
  );
}

async function dedupeNow() {
  dedupeButton.disabled = true;
  try {
    const { collapseSubviews } =
      await chrome.storage.sync.get(DEFAULT_SETTINGS);
    const tabs = await chrome.tabs.query({ url: 'https://github.com/*' });
    const ids = duplicateTabIds(tabs, collapseSubviews);

    await Promise.all(
      ids.map((id) => chrome.tabs.remove(id).catch(() => {})),
    );
    if (ids.length > 0) {
      const { tabsDeduped = 0 } =
        await chrome.storage.local.get('tabsDeduped');
      await chrome.storage.local.set({ tabsDeduped: tabsDeduped + ids.length });
      await refreshStats();
    }

    dedupeStatus.textContent =
      ids.length === 0
        ? 'No duplicates found ✨'
        : `Closed ${ids.length} duplicate ${ids.length === 1 ? 'tab' : 'tabs'}`;
  } finally {
    dedupeButton.disabled = false;
  }
}

dedupeButton.addEventListener('click', () => void dedupeNow());

async function init() {
  const settings = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  for (const key of Object.keys(DEFAULT_SETTINGS)) {
    const input = document.getElementById(key);
    input.checked = settings[key];
    input.addEventListener('change', () => {
      chrome.storage.sync.set({ [key]: input.checked });
    });
  }
  await refreshStats();
}

void init();
